                                  "code": "import numpy as np\n\n# Simulasi Perilaku Klaster saat Partisi Jaringan: Sistem CP vs Sistem AP\nclass Node:\n    def __init__(self, name):\n        self.name = name\n        self.value = 0\n\nclass DistributedCluster:\n    def __init__(self, mode=\"CP\"):\n        self.mode = mode  # \"CP\" atau \"AP\"\n        self.partition_A = [Node(\"node_1\"), Node(\"node_2\")]  # Mayoritas (2 node)\n        self.partition_B = [Node(\"node_3\")]                 # Minoritas (1 node)\n        self.is_partitioned = False\n\n    def write(self, target_partition, new_val):\n        target_nodes = self.partition_A if target_partition == \"A\" else self.partition_B\n        \n        if self.is_partitioned:\n            if self.mode == \"CP\":\n                # Sistem CP: Hanya menerima tulis jika berada di partisi kuorum mayoritas\n                if len(target_nodes) >= 2:\n                    for n in target_nodes: n.value = new_val\n                    return True, \"TULIS SUKSES (Kuorum Mayoritas Partisi A)\"\n                else:\n                    return False, \"TULIS DITOLAK (Partisi B Terisolasi - Menjaga Konsistensi)\"\n            elif self.mode == \"AP\":\n                # Sistem AP: Menerima tulis di manapun demi ketersediaan 100%\n                for n in target_nodes: n.value = new_val\n                return True, \"TULIS SUKSES (Ketersediaan Lokal Diprioritaskan)\"\n        else:\n            for n in self.partition_A + self.partition_B: n.value = new_val\n            return True, \"TULIS SUKSES GLOBAL\"\n\n# Uji Coba Simulasi Skenario Pemutusan Jaringan\ncp_cluster = DistributedCluster(mode=\"CP\")\ncp_cluster.is_partitioned = True\n\nap_cluster = DistributedCluster(mode=\"AP\")\nap_cluster.is_partitioned = True\n\nok_cp_min, msg_cp_min = cp_cluster.write(\"B\", 999)\nok_ap_min, msg_ap_min = ap_cluster.write(\"B\", 999)\n\nprint(\"Evaluasi Eksperimental Teorema CAP (Gilbert & Lynch, 2002):\")\nprint(f\"  [Sistem CP pada Partisi Minoritas] Status: {ok_cp_min} | Respon: {msg_cp_min}\")\nprint(f\"  [Sistem AP pada Partisi Minoritas] Status: {ok_ap_min}  | Respon: {msg_ap_min}\")\nprint(\"  Kesimpulan Matematis: Tidak ada sistem terdistribusi yang dapat mencapai C dan A secara bersamaan saat P terjadi!\")",
