                                  "code": "# Simulator Algoritma Slowly Changing Dimensions Type 2 (dbt Snapshot Engine)\nimport hashlib\nfrom datetime import datetime, timezone\n\nclass DBTSnapshotSimulator:\n    def __init__(self, monitored_columns):\n        self.monitored_columns = monitored_columns\n        self.snapshot_table = []\n        \n    def _compute_checksum(self, row):\n        payload = '|'.join(str(row.get(c, '')) for c in self.monitored_columns)\n        return hashlib.md5(payload.encode('utf-8')).hexdigest()[:8]\n        \n    def run_snapshot(self, current_source_rows, current_ts_str):\n        active_records = {r['id']: r for r in self.snapshot_table if r['dbt_valid_to'] is None}\n        \n        for src_row in current_source_rows:\n            row_id = src_row['id']\n            src_hash = self._compute_checksum(src_row)\n            \n            if row_id not in active_records:\n                # Entitas Baru: Sisipkan rekor aktif perdana\n                new_entry = dict(src_row)\n                new_entry.update({'_hash': src_hash, 'dbt_valid_from': current_ts_str, 'dbt_valid_to': None})\n                self.snapshot_table.append(new_entry)\n            else:\n                curr_entry = active_records[row_id]\n                if curr_entry['_hash'] != src_hash:\n                    # Perubahan Terdeteksi: Tutup rekor lama dan sisipkan rekor baru (SCD Type 2)\n                    curr_entry['dbt_valid_to'] = current_ts_str\n                    new_entry = dict(src_row)\n                    new_entry.update({'_hash': src_hash, 'dbt_valid_from': current_ts_str, 'dbt_valid_to': None})\n                    self.snapshot_table.append(new_entry)\n\nsnapshot_engine = DBTSnapshotSimulator(monitored_columns=['tier', 'alamat'])\n\n# Hari 1: Status Pelanggan Awal\nday1_data = [{'id': 101, 'nama': 'Budi', 'tier': 'Silver', 'alamat': 'Jakarta'}]\nsnapshot_engine.run_snapshot(day1_data, '2026-09-01 00:00:00')\n\n# Hari 20: Pelanggan Budi upgrade ke Gold dan pindah ke Bali\nday20_data = [{'id': 101, 'nama': 'Budi', 'tier': 'Gold', 'alamat': 'Bali'}]\nsnapshot_engine.run_snapshot(day20_data, '2026-09-20 12:00:00')\n\nprint('Hasil Pelacakan Riwayat dbt Snapshot (SCD Type 2):')\nfor row in snapshot_engine.snapshot_table:\n    print(f\"  ID: {row['id']} | Tier: {row['tier']} | Valid From: {row['dbt_valid_from']} -> Valid To: {row['dbt_valid_to']}\")\nprint('Kesimpulan: SCD Type 2 mempertahankan riwayat perubahan data tanpa menimpa masa lalu.')",
